queries.cql:
// CrowdStrike CQL for Crypto-Terror/Narco Nexus Detection
// Detects sanctions-exposed wallet transactions and peel chain patterns through mixers
(transaction_type="crypto_transfer" OR transaction_type="crypto_deposit" OR transaction_type="crypto_withdrawal")
amount_usd>=1000
(sdn_hop_distance<=2 OR (mixing_service_interaction="true" AND peel_chain_detected="true"))
| chain_classification := case {
    sdn_hop_distance<=1 -> "direct_sdn_exposure";
    sdn_hop_distance==2 -> "indirect_sdn_exposure";
    mixing_service_interaction=="true" AND peel_chain_detected=="true" -> "peel_chain_mixing";
    * -> "unknown";
  }
| groupBy(wallet_address, function=[
    collect([counterparty_wallet, amount_usd, crypto_currency, transaction_date,
             sdn_hop_distance, sdn_entity_name, mixing_service_interaction,
             peel_chain_detected, consolidation_wallet_risk_score,
             chain_classification]),
    sum(amount_usd, as=total_volume)
  ])
| sort(total_volume, order=desc)
